def model(key,n,y,x=65):
 els=[t(y,'Tens',12,x=x,width=235),t(y,'Ones',12,x=x+300,width=175)]
 for i in range(n//10): els.append(dict(type='bundle',id=f'{key}-ten-{i}',x=x+i*67,top=y+40,scale=.72))
 els.append(dict(type='objects',id=key+'-ones',kind='strip',count=n%10,points=[[x+300+(i%5)*21,y+40+(i//5)*48] for i in range(n%10)],scale=.72))
 diagrams.append(dict(id=key,value=n));return els
